from pathlib import Path
import html, json, re
R=Path(__file__).resolve().parents[1]
A=R/'assets/images'
photos=sorted([f for f in A.rglob('*') if f.suffix.lower() in ('.jpg','.jpeg','.png','.webp','.gif') and f.is_file()])
photo_urls=['/'+p.relative_to(R).as_posix() for p in photos]
nav=[('Startseite','/'),('Unsere Arbeit','/projekte/'),('Über NAHOW','/ueber-uns/'),('Einblicke','/einblicke/'),('Unterstützen','/unterstuetzen/'),('Kontakt','/kontakt/')]
CSS='/assets/site.css'
def named(n):
 u='/assets/images/'+n
 return photo_urls.index(u) if u in photo_urls else 10**6
EXCLUDE=('Africa-map','Generalanzeiger','althof','vyvian','nahow_image_collage','Nahow_Presse','Spende_Sekundarschule','Nahow_Spenden')
gallery_urls=[u for u in photo_urls if not any(x in u for x in EXCLUDE)]
def img(i,alt='',cls=''):
 if i>=len(photo_urls): return '<div class="image-unavailable"><span>Originalaufnahme aus dem NAHOW-Archiv</span><small>Bild erscheint nach unverändertem Import</small></div>'
 return f'<img class="{cls}" src="{photo_urls[i]}" alt="{html.escape(alt)}" loading="lazy" decoding="async">'
def card(title,body,url,tag):return f'<a class="work-card" href="{url}"><span class="eyebrow">{tag}</span><h3>{title}</h3><p>{body}</p><span class="arrow">Mehr erfahren <b>↗</b></span></a>'
def layout(title,desc,content,active='/',canonical=None):
 items=''.join(f'<a href="{url}" class="{"active" if url==active else ""}">{label}</a>' for label,url in nav)
 base=canonical or active
 return f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#15392d"><meta name="description" content="{html.escape(desc,quote=True)}"><link rel="canonical" href="https://nahow.de{base}"><link rel="stylesheet" href="{CSS}"><title>{title} | NAHOW e.V.</title></head><body><a href="#inhalt" class="skip">Zum Inhalt springen</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="NAHOW e.V. Startseite"><span class="brand-mark">n<span>·</span></span><span class="brand-copy">NAHOW <small>e.V. · Gemeinsam vor Ort</small></span></a><button class="menu-toggle" aria-label="Menü öffnen" aria-expanded="false" aria-controls="main-nav">Menü <span>☰</span></button><nav class="nav" id="main-nav" aria-label="Hauptnavigation">{items}</nav></div></header><main id="inhalt">{content}</main><footer class="footer"><div class="wrap"><div class="footer-top"><div><span class="footer-brand">NAHOW e.V.</span><p>Engagement für Bildung, Lebensgrundlagen und Umwelt — gemeinsam mit Menschen in Kamerun.</p></div><div><h4>Entdecken</h4><a href="/projekte/">Projekte</a><a href="/berichte/">Berichte</a><a href="/einblicke/">Originalfotos</a></div><div><h4>Verbindung</h4><a href="mailto:mail@nahow.de">mail@nahow.de</a><a href="/kontakt/">Kontakt</a><a href="/unterstuetzen/">Spenden</a></div></div><div class="footer-bottom"><span>© NAHOW e.V.</span><div><a href="/impressum/">Impressum</a><a href="/datenschutz/">Datenschutz</a></div></div></div></footer><script src="/assets/site.js" defer></script></body></html>'''
def intro(kicker,title,desc):return f'<section class="page-intro"><div class="wrap"><span class="eyebrow">{kicker}</span><h1>{title}</h1><p class="lead">{desc}</p></div></section>'
def section(h,t,body):return f'<section class="section"><div class="wrap"><div class="section-heading"><span class="eyebrow">{h}</span><h2>{t}</h2></div>{body}</div></section>'
pages={}
hero=f'''<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><span class="eyebrow light">Gemeinsam etwas bewegen · Kamerun</span><h1>Veränderung beginnt <em>vor Ort.</em></h1><p>Seit vielen Jahren engagiert sich NAHOW e.V. gemeinsam mit lokalen Gemeinschaften für Bildung, bessere Lebensgrundlagen und eine nachhaltigere Zukunft.</p><div class="actions"><a class="btn btn-light" href="/projekte/">Unsere Arbeit entdecken <span>↗</span></a><a class="text-link" href="/ueber-uns/">Unsere Geschichte <span>↗</span></a></div></div><div class="hero-media">{img(named('Kinder1_Enwen.png'),'Kinder auf einem Hügel in Enwen, Kamerun (Originalfoto)')}<div class="hero-index">01 / Projekte. Menschen. Perspektiven.</div></div></div><div class="hero-bottom wrap"><span>Ein Verein. Eine gemeinsame Verantwortung.</span><span>Enwen · Kamerun</span></div></section>'''
focus=section('Was uns antreibt','Aus konkreten Bedürfnissen entstehen nachhaltige Lösungen.',f'<div class="cards">{card("Bildung ermöglichen","Schulen, berufliche Ausbildung und praktische Perspektiven für junge Menschen.","/projekte/#bildung","01 / BILDUNG")}{card("Umwelt schützen","Aufforstung und ressourcenschonende Kochtechnologien als langfristiges Ziel.","/projekte/#umwelt","02 / UMWELT")}{card("Gemeinschaften stärken","Zusammenarbeit mit lokalen Partnern bei Projekten, die vor Ort gebraucht werden.","/projekte/#gemeinschaft","03 / GEMEINSCHAFT")}</div>')
history=f'''<section class="story-band"><div class="wrap split"><div class="story-photo">{img(named('new-field_Enwen.png'),'Schule und neu hergerichtetes Fußballfeld in Enwen (Originalfoto)')}</div><div class="story-text"><span class="eyebrow">Unsere Wurzeln</span><h2>Verbunden mit Enwen. Engagiert für morgen.</h2><p>Die Geschichte von NAHOW begann mit dem Wunsch, gemeinsam mit den Menschen in Enwen konkrete Verbesserungen zu ermöglichen. Von einer Dorfschule und beruflicher Ausbildung bis zu heutigen Umweltzielen: Unsere Arbeit entwickelt sich mit den Bedürfnissen vor Ort.</p><a class="inline-link" href="/ueber-uns/">Mehr über NAHOW <span>↗</span></a></div></div></section>'''
report=section('Transparenz','Nicht nur Ziele. Auch die bisherige Arbeit.', '<div class="report-strip"><p>Projektberichte und Dokumentation gehören zu unserer Geschichte. Entdecken Sie abgeschlossene Projekte und vorhandene Berichte.</p><a class="btn btn-outline" href="/berichte/">Zu den Berichten ↗</a></div>')
cta='<section class="cta"><div class="wrap cta-flex"><div><span class="eyebrow light">Gemeinsam weiterkommen</span><h2>Unterstützung, die vor Ort ankommt.</h2><p>Entdecken Sie Möglichkeiten, unsere Arbeit zu begleiten.</p></div><a class="btn btn-light" href="/unterstuetzen/">NAHOW unterstützen ↗</a></div></section>'
pages['/']=layout('Gemeinsam vor Ort','NAHOW e.V. engagiert sich in Kamerun für Bildung, Umwelt und Lebensgrundlagen.',hero+focus+history+report+cta)
work=intro('Unsere Arbeit','Menschen und Möglichkeiten.','Einblicke in frühere Projekte sowie die Schwerpunkte, die NAHOW heute verfolgt.')
work+='''<section class="section"><div class="wrap"><div class="project-row" id="bildung"><div><span class="eyebrow">Bildung · Abgeschlossene Projekte</span><h2>Eine Dorfschule mit Zukunft.</h2><p>NAHOW unterstützte den Wiederaufbau einer Dorfschule und die Herrichtung eines Fußballfeldes. Die Einweihung fand im August 2010 statt.</p><a class="inline-link" href="/berichte/">Projektberichte ansehen ↗</a></div>'''+img(named('new-field_Enwen.png'),'Schule und Fußballfeld in Enwen (Originalfoto)')+'''</div><div class="project-row reverse" id="gemeinschaft"><div><span class="eyebrow">Berufliche Perspektiven</span><h2>Ausbildung, die Möglichkeiten schafft.</h2><p>Ein Ausbildungszentrum für Schneiderei und Tischlerei gehörte zu den dokumentierten Initiativen. Ergänzend wurden Themen wie Ernährung und praktische Erwerbsmöglichkeiten behandelt.</p><a class="inline-link" href="/berichte/">Projektberichte ansehen ↗</a></div>'''+img(named('DSC_0293_Enwen-scaled.png'),'Neu gefertigte Schulbänke in Enwen (Originalfoto)')+'''</div><div class="project-row" id="umwelt"><div><span class="eyebrow">Umwelt · Ziele</span><h2>Aufforstung und effiziente Energienutzung.</h2><p>Das Ziel, eine Million Bäume zu pflanzen, ist ein Vorhaben — keine Angabe bereits gepflanzter Bäume. Daneben stehen effiziente Kochtechnologien und Biogas im Fokus.</p><a class="inline-link" href="/unterstuetzen/">Engagement unterstützen ↗</a></div>'''+img(named('Ausblick_aus_dem_Klassenzimmer_Enwen-e1714048885483.png'),'Bananenpflanzen in Enwen, Blick aus dem Klassenzimmer (Originalfoto)')+'''</div></div></section>'''+cta
pages['/projekte/']=layout('Unsere Projekte','Schule, Ausbildung, Aufforstung und energieeffizientes Kochen: die Arbeit von NAHOW e.V.',work,'/projekte/')
about=intro('Über uns','Verwurzelt in Enwen.','NAHOW e.V. verbindet langfristiges Engagement mit Zusammenarbeit vor Ort.')
about+=section('Unsere Geschichte','Aus einer Begegnung wurde eine Aufgabe.','<div class="narrow prose"><p>Der Verein entstand aus dem Wunsch heraus, Menschen in der Region Enwen in Kamerun bei konkreten Herausforderungen zu unterstützen. Bildung und Gesundheitsversorgung gehörten zu den frühen Tätigkeitsfeldern.</p><p>Heute gehören Aufforstung, effizientere Kochmethoden und nachhaltige Energienutzung zu den erklärten Zielen. Vergangene Erfolge, aktuelle Projekte und zukünftige Vorhaben werden dabei bewusst unterschieden.</p></div>')
about+=section('Menschen hinter NAHOW','Das Team','<div class="team"><article><h3>Tichi Mbanwie</h3><p>Vorsitzender</p></article><article><h3>Michael Althof</h3><p>Kassenwart</p></article><article><h3>Vyvian Mbanwie</h3><p>Koordinator USA</p></article></div><p class="small-note">Die Namen und Funktionen entsprechen dem bisher veröffentlichten Teamverzeichnis.</p>')+cta
